    s += `<text class="g-clabel g-curve-1" x="258" y="70" text-anchor="middle"><tspan style="text-decoration:overline">A</tspan></text><text class="g-label" x="258" y="88" text-anchor="middle">« aucun 0 » :</text><text class="g-label" x="258" y="104" text-anchor="middle">9⁴ codes</text>`;
