      const ech = t === 1, L = ech ? pick([2.5, 3, 3.5, 4, 4.5, 5, 6]) : pick([15, 20, 25, 30, 35, 40, 50, 60]), [k, d] = pick(ANG), f = pick(["sin", "cos"]), a = (k * Math.PI) / d;
      const v = L * (f === "sin" ? Math.sin(a) : Math.cos(a)), p = ech ? 2 : 1, rep = +v.toFixed(p), exact = Math.abs(v - rep) < 1e-9;
