      const k = pick([1, 2, 3, 5]), cc = pick([0, 0, 1, 2, -1, 3]), nomF = cc === 0 && k === 1 ? "inverse" : pick(["f", "g"]);
      const corps = cc === 0 ? `${k} / x` : `${k} / (x ${cc > 0 ? "-" : "+"} ${Math.abs(cc)})`, fT = cc === 0 ? `\\dfrac{${k}}{x}` : `\\dfrac{${k}}{${poly([1, -cc])}}`;
      const c = melangeChoix(`Python s'arrête sur une erreur : il doit calculer $\\texttt{${nomF}(${cc})}$, une division par $0$`, ["Les valeurs se rapprochent de $0$", `Les valeurs se rapprochent de $${-k}$`, "Les valeurs deviennent de plus en plus grandes"]);
      return {
        enonce: `${prog(`def ${nomF}(x):\n    return ${corps}\n\n`, nomF, cc, K)}\n\nQue se passe-t-il quand on lance ce programme ?`,
        mode: "choix", choix: c.choix, attendu: c.attendu,
        aides: ["Regarde ce que calcule $\\texttt{taux(f, a, h)}$ : il a besoin de $\\texttt{f(a + h)}$ **et** de $\\texttt{f(a)}$.", `Ici, $a = ${cc}$ : il faut calculer $\\texttt{${nomF}(${cc})}$.`, `La fonction $x \\mapsto ${fT}$ n'est pas définie en $${cc}$.`],
        solution: `Pour calculer le taux, Python doit évaluer $\\texttt{${nomF}(${cc})}$, c'est-à-dire $\\dfrac{${k}}{0}$ : il s'arrête avec une erreur (ZeroDivisionError). La fonction $x \\mapsto ${fT}$ n'est pas définie en $${cc}$, donc on ne peut même pas parler de nombre dérivé en $${cc}$.`
      };
