    const u = [B[0] - A[0], B[1] - A[1]], w = [C[0] - A[0], C[1] - A[1]], v = u[0] * w[0] + u[1] * w[1];
    if ((!u[0] && !u[1]) || (!w[0] && !w[1]) || (B[0] === C[0] && B[1] === C[1])) return GEN["ps-coordonnees"]();
