  // f(x) = a + b / (x − c) ; asym : asymptotes en pointillés (sinon la courbe seule)
  function tlfHyperbole(a, b, c, aria, asym) {
    const f = (x) => a + b / (x - c), lo = c - 5, hi = c + 6, e = 0.18 * Math.abs(b) ** 0.5;
    // le nom Cf va près de la branche de droite, ou de celle de gauche s'il n'y trouve pas de place libre
    const nom = (k) => (k ? { label: "C<tspan class=\"sub\" dy=\"3\">f</tspan>", auto: true, lx: hi, dx: -4, dy: b > 0 ? -10 : 18 } : { label: "C<tspan class=\"sub\" dy=\"3\">f</tspan>", auto: true });
    const opts = (k) => tsuEtiquettes({ xmin: lo - 0.4, xmax: hi + 0.4, ymin: a - 6, ymax: a + 6, h: 300, curves: [Object.assign({ f, a: lo, b: c - e, closed: false }, k ? {} : nom(0)), Object.assign({ f, a: c + e, b: hi, closed: false }, k ? nom(1) : {})], chemins: asym === false ? [] : [[[lo - 0.4, a], [hi + 0.4, a]], [[c, a - 6], [c, a + 6]]], aria });
    let o = opts(1);
    if (!o.curves[1].place) { const o0 = opts(0); if (o0.curves[0].place) o = o0; }
    return graph(o)
      .replace(/class="g-curve g-curve-1" (d="[^"]*")\/>/g, 'class="g-curve g-curve-0" $1/>').replace(/g-clabel g-curve-1/g, "g-clabel g-curve-0"); // les deux branches de la même couleur
  }
