    [1, 2, 3].forEach((k) => { const y = 18 + 22 * (k - 1); for (let i = 0; i < k; i++) s += `<circle class="g-point" cx="${140 + (i - (k - 1) / 2) * 20}" cy="${y}" r="7"/>`; s += `<text class="g-label" x="250" y="${y + 4}">${k} ${nom}</text>`; });
    [84, 92, 100].forEach((y) => { s += `<circle class="g-end" cx="140" cy="${y}" r="1.8"/>`; });
    [0, 1, 2, 3, 5, 6, 7, 8].forEach((i) => { s += `<circle class="g-point" cx="${60 + i * 20}" cy="124" r="7"/>`; });
