    for (let k = 1; k <= 2; k++) for (let i = 0; i < q ** k; i++) s += `<line class="g-droite" x1="${X(k - 1, Math.floor(i / q))}" y1="${Y[k - 1]}" x2="${X(k, i)}" y2="${Y[k]}"/>`;
    for (let k = 0; k <= 2; k++) { for (let i = 0; i < q ** k; i++) s += `<circle class="g-point" cx="${X(k, i)}" cy="${Y[k]}" r="7"/>`; s += `<text class="g-label" x="6" y="${Y[k] + 4}">jour ${k}</text>`; }
