    if (t === "exp") { const p = poly([m, b, 0]), dp = poly([2 * m, b]); return { du: dp, f: `e^{${p}}`, u: p, v: "e^x", d: `(${dp})e^{${p}}`, faux: [`e^{${p}}`, `(${p})e^{${p}}`, `(${dp})e^{${dp}}`] }; }
