  FIGURES["lsu-cours-escalier"] = () => tsEscalier((x) => Math.sqrt(x + 6), 1, 4, 4.8, 4, "Escalier de la suite u(n+1) = racine de (u(n) + 6) partant de 1 : les termes montent vers 3, abscisse du point d'intersection de la courbe et de la droite y = x");
