      if (k === "conv") { const l = rand(-3, 6), c = pick([-4, -3, -2, 2, 3, 4]), q = pick([0.5, 0.6, 0.7, -0.6, -0.5]); f = (n) => l + c * q ** n; L = l; }
      else if (k === "plus") { const a = pick([0.5, 1, 1.5, 2]), b = rand(-3, 3); f = Math.random() < 0.5 ? (n) => a * n + b : (n) => 0.1 * a * n * n + b; L = Infinity; }
      else if (k === "moins") { const a = pick([0.5, 1, 1.5]), b = rand(0, 6); f = (n) => -a * n + b; L = -Infinity; }
