  GEN["bin-python"] = function () {
    const t = pick(["proba", "cumul", "simul"]), n = rand(4, 15), [p, ps] = pick([[0.2, "0.2"], [0.3, "0.3"], [0.5, "0.5"], [0.25, "0.25"], [0.4, "0.4"], [0.1, "0.1"]]);
    // une valeur dont la 5e décimale est un 5 « pile » s'arrondit différemment selon Python et le calcul exact : on l'évite
    const ambigu = (x) => Math.abs(x * 1e4 - Math.floor(x * 1e4) - 0.5) < 1e-6;
    if (t === "proba") {
      const k = rand(0, Math.min(n, 6)), x = bnP(n, p, k), r = bnR(x, 4);
      if (ambigu(x)) return GEN["bin-python"]();
      return {
        enonce: `Qu'affiche ce programme ? (il arrondit à $4$ décimales)\n\n\`\`\`python\nfrom math import comb\n\nn, p, k = ${n}, ${ps}, ${k}\nprint(round(comb(n, k) * p**k * (1 - p)**(n - k), 4))\n\`\`\``,
        mode: "nombre", prefixe: "Affichage :", attendu: r, tolerance: 0.00005 + 1e-9,
        erreurs: [{ valeur: bnR(p ** k * (1 - p) ** (n - k), 4), message: "$\\texttt{comb(n, k)}$ fait partie du calcul : n'oublie pas le coefficient binomial." }],
        aides: ["$\\texttt{comb(n, k)}$ calcule le coefficient binomial $\\dbinom{n}{k}$.", `Le programme calcule $P(X = ${k})$ pour $X$ de loi $\\mathcal{B}(${n}\\,;${fr(p)})$.`, "Calcule à la calculatrice et arrondis à $4$ décimales."],
        solution: `Il affiche $P(X = ${k}) = \\dbinom{${n}}{${k}} \\times ${fr(p)}^{${k}} \\times ${fr(1 - p)}^{${n - k}} \\approx ${nb(r)}$.`
      };
    }
    if (t === "cumul") {
      const k = rand(1, Math.min(n - 1, 5)), x = bnCum(n, p, k), r = bnR(x, 4);
      if (ambigu(x)) return GEN["bin-python"]();
      return {
        enonce: `Qu'affiche ce programme ? (il arrondit à $4$ décimales)\n\n\`\`\`python\nfrom math import comb\n\ndef f(n, p, k):\n    s = 0\n    for i in range(k + 1):\n        s = s + comb(n, i) * p**i * (1 - p)**(n - i)\n    return s\n\nprint(round(f(${n}, ${ps}, ${k}), 4))\n\`\`\``,
        mode: "nombre", prefixe: "Affichage :", attendu: r, tolerance: 0.00005 + 1e-9,
        erreurs: [{ valeur: bnR(bnCum(n, p, k - 1), 4), message: `$\\texttt{range(${k + 1})}$ va jusqu'à $${k}$ inclus.` }, { valeur: bnR(bnP(n, p, k), 4), message: `La boucle additionne plusieurs termes : ce n'est pas seulement $P(X = ${k})$.` }],
        aides: [`La boucle additionne $P(X = i)$ pour $i$ de $0$ à $${k}$.`, `$\\texttt{f(${n}, ${ps}, ${k})}$ calcule donc $P(X \\leqslant ${k})$.`, "Utilise la fonction de cumul de la calculatrice."],
        solution: `La fonction calcule $P(X \\leqslant ${k})$ pour $X$ de loi $\\mathcal{B}(${n}\\,;${fr(p)})$ : le programme affiche $${nb(r)}$.`
      };
    }
    const ms = melangeChoix(`Le nombre de succès dans un schéma de Bernoulli de paramètres $${n}$ et $${fr(p)}$`, [`La probabilité d'obtenir $${n}$ succès`, `Le nombre d'échecs avant le premier succès`, `La fréquence des succès sur $${n}$ essais`]);
    return {
      enonce: `Que renvoie la fonction $\\texttt{simul()}$ ?\n\n\`\`\`python\nfrom random import random\n\ndef simul():\n    x = 0\n    for i in range(${n}):\n        if random() < ${ps}:\n            x = x + 1\n    return x\n\`\`\``,
      mode: "choix", choix: ms.choix, attendu: ms.attendu,
      aides: ["$\\texttt{random()}$ donne un nombre au hasard dans $[0\\,;1[$ : la condition $\\texttt{random() < " + ps + "}$ est vraie avec la probabilité $" + fr(p) + "$.", `La boucle répète $${n}$ fois cette épreuve, de façon indépendante.`, "$\\texttt{x}$ compte les succès."],
      solution: `Chaque tour de boucle est une épreuve de Bernoulli de paramètre $${fr(p)}$, et $\\texttt{x}$ compte les succès : $\\texttt{simul()}$ simule une variable aléatoire de loi $\\mathcal{B}(${n}\\,;${fr(p)})$.`
    };
  };

  /* ---------- Terminale spécialité, chapitre 6 : limites de fonctions (préfixe lfo-) ---------- */
  const LFO_I = "+\\infty", LFO_MI = "-\\infty";
  const lfoL = (v) => (v === Infinity ? `$${LFO_I}$` : v === -Infinity ? `$${LFO_MI}$` : v === null ? "Pas de limite" : `$${typeof v === "string" ? v : nb(v)}$`);
  const lfoChoix = (bonne, pieges) => melangeChoix(lfoL(bonne), [...new Set(pieges.map(lfoL))].filter((x) => x !== lfoL(bonne)).concat([`$${LFO_I}$`, "$0$", `$${LFO_MI}$`, "$1$"].filter((x) => x !== lfoL(bonne))));
  const lfoTx = (v) => (v === Infinity ? LFO_I : v === -Infinity ? LFO_MI : typeof v === "string" ? v : nb(v));
  const lfoCo = (k) => (k === 1 ? "" : k === -1 ? "-" : `${k}`); // coefficient devant une expression
  // Hyperbole y = A + B/(x - c) tracée sans sortir de la fenêtre [ymin ; ymax]
  function lfoHyper(A, B, c, xmin, xmax, ymin, ymax, label) {
    const f = (x) => A + B / (x - c);
    const marge = (y) => Math.abs(B / (y - A));
    const dG = B > 0 ? marge(ymin) : marge(ymax), dD = B > 0 ? marge(ymax) : marge(ymin);
    return [{ f, a: xmin, b: c - dG, closed: false }, { f, a: c + dD, b: xmax, closed: false, couleur: 0, label, lx: xmax - 0.3, dx: -4, dy: B > 0 ? -8 : 16 }];
  }
