        erreurs: [{ valeur: m / k, message: "Tu as inversé : $\\dfrac{\\sin(kx)}{mx} = \\dfrac{k}{m} \\times \\dfrac{\\sin(kx)}{kx}$." }, { valeur: 1, message: `$\\dfrac{\\sin(${k}x)}{${m}x}$ n'est pas de la forme $\\dfrac{\\sin X}{X}$ : fais apparaître $${k}x$ au dénominateur.` }, { valeur: k, message: `N'oublie pas le $${m}$ du dénominateur.` }, ...tsApprox(L)].filter((e) => e.valeur !== L),
